import uiautomation as auto, time
auto.SetGlobalSearchTimeout(2)
root=auto.ControlFromHandle(8456336)
target=None
for c in root.GetChildren():
    pass
def walk(c,depth=0):
    global target
    if target is not None or depth>9: return
    try:
        if c.ControlTypeName=="TabItemControl" and "Native Connector Implementation" in (c.Name or ""):
            target=c; return
        for k in c.GetChildren(): walk(k,depth+1)
    except Exception: return
walk(root)
if not target:
    print("NO_TARGET"); raise SystemExit(2)
pat=target.GetSelectionItemPattern()
if pat: pat.Select()
else: target.SetFocus()
time.sleep(0.8)
print("SELECTED",repr(target.Name))
# enumerate visible document/edit/button controls after selection
def walk2(c,depth=0):
    if depth>12: return
    try:
        typ=c.ControlTypeName
        name=c.Name or ""
        if typ in ("EditControl","DocumentControl","ButtonControl","TextControl") and (typ!="TextControl" or len(name)<200):
            if typ!="TextControl" or any(x in name.lower() for x in ["максим","новый чат","ask","спрос","stop","отправ","send","высок","high"]):
                print(depth,typ,repr(name),repr(c.AutomationId),repr(c.ClassName))
        for k in c.GetChildren(): walk2(k,depth+1)
    except Exception: return
walk2(root)
